-- 312 · Contrato, Terms of Use e Invoicing and Payment Collection Agreement do
-- parceiro, versão 2026-10-06 (modelo de agente: Schedule A = reservas da
-- plataforma, Fixfy agente do parceiro; Schedule B = trabalho B2B, Fixfy
-- principal com self-billing). INATIVOS: is_active = false.
--
-- Fonte: ~/Desktop/Fixfy - documentos agente 2026-10-06/ (05, 06 e 07, com o
-- Anexo 1 = declaração de VAT do parceiro). HTML no mesmo padrão .fx-doc da 297.
-- O Invoicing and Payment Collection Agreement substitui o Self-Billing
-- Agreement 2026-09-22 e por isso usa o tipo self_bill_agreement.
--
-- NÃO ATIVAR SEM O DONO. Aplicar esta migration só grava as versões; o app
-- continua pedindo as de 2026-09-22 até alguém rodar o bloco comentado no fim.
-- A Commission Schedule (08) é anexo publicado à parte, não é um contract_type.
--
-- Idempotente: cada INSERT só grava se ainda não existir a mesma versão do tipo.

INSERT INTO public.contract_versions (contract_type, version, title, body_html, is_active)
