.fx-doc header.brand{display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:3px solid var(--coral);padding-bottom:12px}
.fx-doc .logo-img{display:block;height:36px;width:auto;max-width:100%}
.fx-doc header.brand .meta{font-size:8.5pt;color:var(--grey);text-align:right;line-height:1.45}
